+function drawGrid(){const grid=el('#charGrid');grid.innerHTML='';fighters.forEach((f,i)=>{let b=document.createElement('button');b.className='char-card'+(i>=unlocked?' locked':'')+(i===selected?' chosen':'');b.innerHTML=`${i>=unlocked?'<span class="lock">🔒</span>':''}<span class="portrait">${f.emoji}</span><b>${f.name}</b><small>${i>=unlocked?`Clear stage ${Math.min(i-4,9)} to unlock`:f.style}</small>`;b.onclick=()=>{if(i>=unlocked){el('#charInfo').innerHTML=`<b>${f.name}</b> joins your crew after clearing stage ${i-4}.`;return}selected=i;costume=0;updateCharInfo();drawGrid()};grid.appendChild(b)});updateCharInfo()}
+function updateCharInfo(){let f=fighters[selected];el('#charInfo').innerHTML=`<b>${f.name}</b> · ${f.style} &nbsp; <span style="color:#ffcf74">${f.special}</span><br><span style="color:#978da3">${f.bio} &nbsp; · &nbsp; <button id="costumeBtn" style="background:none;border:0;color:#ff9cad;padding:0;text-decoration:underline;font-size:11px">COSTUME ${costume+1}/3 ↻</button></span>`;el('#costumeBtn').onclick=()=>{costume=(costume+1)%3;updateCharInfo()}}
+function openSelect(){screen='select';drawGrid();selectOverlay.hidden=false}
+el('#playBtn').onclick=openSelect;el('#closeSelect').onclick=()=>{selectOverlay.hidden=true;screen='menu'};
+el('#startRun').onclick=()=>{selectOverlay.hidden=true;startOverlay.hidden=true;endOverlay.hidden=true;beginGame()};
+el('#continueBtn').onclick=()=>{startOverlay.hidden=true;beginGame()};
+el('#againBtn').onclick=()=>{endOverlay.hidden=true;beginGame()};el('#homeBtn').onclick=()=>{endOverlay.hidden=true;startOverlay.hidden=false;screen='menu';el('#statusText').textContent='STORY MODE'};
+function beginGame(){stage=0;score=0;enemies.length=0;gameTime=0;combo=0;player={x:170,y:365,hp:100,max:100,face:1,attack:0,special:0,stun:0,iframes:0,walk:0};screen='game';stageBanner=2.5;spawnTimer=.6;el('#statusText').textContent='DISTRICT 01';el('#footerText').textContent='0 POINTS';spawnWave()}
+function spawnWave(){let count=stage===8?1:3+Math.min(stage,3);for(let i=0;i<count;i++){let types=stage===8?['boss']:['grunt','grunt','runner','brute'];let type=types[Math.floor(Math.random()*types.length)];enemies.push({x:650+i*95,y:350+Math.random()*65,hp:type==='boss'?250:type==='brute'?70:40,max:type==='boss'?250:type==='brute'?70:40,type,face:-1,attack:0,stun:0,iframes:0,walk:Math.random()*5})}}
+function nextStage(){stage++;if(stage>=9){winGame();return}enemies.length=0;player.hp=Math.min(100,player.hp+22);player.special=Math.min(100,player.special+30);stageBanner=2.4;spawnTimer=.8;el('#statusText').textContent=`DISTRICT 0${stage+1}`;spawnWave()}

