function nextStage(){stage++;if(stage>=9){winGame();return}enemies.length=0;player.hp=Math.min(100,player.hp+22);player.special=Math.min(100,player.special+30);stageBanner=2.4;spawnTimer=.8;el('#statusText').textContent=`DISTRICT 0${stage+1}`;spawnWave()}
function winGame(){screen='end';el('#endEyebrow').textContent='CITY SAVED · 9 / 9';el('#endTitle').textContent='THE CITY LIVES.';el('#endCopy').textContent=`Count Vesper has fallen. ${fighters[selected].name} and the crew held the line until sunrise. Final score: ${score.toLocaleString()} points.`;endOverlay.hidden=false;cleared=Math.max(cleared,9);unlocked=12;localStorage.setItem('nightfall-unlocked',unlocked);localStorage.setItem('nightfall-cleared',cleared);}
function loseGame(){screen='end';el('#endEyebrow').textContent='KNOCKED OUT · DISTRICT '+String(stage+1).padStart(2,'0');el('#endTitle').textContent='THE NIGHT WINS.';el('#endCopy').textContent=`You scored ${score.toLocaleString()} points. Keep fighting to unlock more of the crew.`;endOverlay.hidden=false;let newUnlock=Math.min(12,6+Math.floor(score/550));unlocked=Math.max(unlocked,newUnlock);localStorage.setItem('nightfall-unlocked',unlocked);localStorage.setItem('nightfall-cleared',Math.max(cleared,stage));}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}
function drawBackground(){let s=stage;let sky=ctx.createLinearGradient(0,0,0,540);sky.addColorStop(0,['#17152a','#291a2b','#18283b','#183138','#171e35','#2d1a26','#151d32','#271622','#321323'][s]);sky.addColorStop(1,'#11101b');rect(0,0,960,540,sky);
