ctx.fillStyle='#ff4d7835';ctx.beginPath();ctx.arc(755,96,60,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f8b5bd';ctx.beginPath();ctx.arc(755,96,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='#302035';ctx.beginPath();ctx.arc(765,89,23,0,Math.PI*2);ctx.fill();
// street layers
