// stage sign
ctx.fillStyle='#fff';ctx.font='bold 12px sans-serif';ctx.globalAlpha=.5;ctx.fillText(stages[stage].toUpperCase(),22,302);ctx.globalAlpha=1;
}
function drawFighter(p,isEnemy=false){if(p.hp<=0)return;let f=isEnemy?null:fighters[selected],x=p.x,y=p.y,baseY=y;
if(p.iframes>0&&Math.floor(gameTime*18)%2===0)return;
