ctx.save();ctx.translate(x,baseY);ctx.scale(p.face,1);
if(isEnemy){let color=p.type==='boss'?'#9b315b':p.type==='brute'?'#647044':p.type==='runner'?'#694b8b':'#813e4c';ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,-29,14,21,0,0,Math.PI*2);ctx.fill();rect(-12,-19,24,23,color);rect(-10,-47,20,16,p.type==='boss'?'#dfbccb':'#bd8f84');rect(-14,-49,7,4,'#341d2d');rect(7,-49,7,4,'#341d2d');rect(-9,-7+walk,8,18,'#211d2b');rect(3,-7-walk,8,18,'#211d2b');rect(-18,-16,8,17,color);rect(10,-16,8,17,color);if(p.type==='boss'){ctx.fillStyle='#ed3d73';ctx.beginPath();ctx.moveTo(-14,-51);ctx.lineTo(-8,-64);ctx.lineTo(-4,-52);ctx.lineTo(3,-66);ctx.lineTo(8,-51);ctx.fill()}}
else{let c=f.color;let skin=f.skin;let outfit=costume===0?c:costume===1?'#e8d8c8':`hsl(${(selected*53+costume*110)%360} 58% 47%)`;
// legs & boots
rect(-10,-15+walk,8,18,'#292333');rect(3,-15-walk,8,18,'#292333');rect(-12,0+walk,12,4,'#100e17');rect(1,0-walk,12,4,'#100e17');
// torso
ctx.fillStyle=outfit;ctx.beginPath();ctx.moveTo(-12,-43);ctx.lineTo(11,-43);ctx.lineTo(14,-16);ctx.lineTo(-14,-16);ctx.fill();rect(-11,-43,22,4,'#ffffff28');
// arms, attack reach
rect(-18,-40,7,21,skin);rect(11,-41,7,20,skin);rect(12+lean,-27,11,8,skin);ctx.fillStyle=outfit;ctx.beginPath();ctx.arc(0,-52,12,0,Math.PI*2);ctx.fill();rect(-11,-58,22,9,f.hair);rect(-4,-52,12,2,'#fff7e988');rect(3,-47,4,2,'#261626');
if(f.weapon==='blade'){ctx.save();ctx.translate(19+lean,-26);ctx.rotate(-.8);rect(-2,-24,4,27,'#c7a466');rect(-3,-34,6,14,'#e8e4ed');ctx.restore()}
if(f.weapon==='staff'){rect(20+lean,-50,3,49,'#c18a48');rect(18+lean,-51,7,3,'#edc571')}
if(f.weapon==='blaster'){rect(18+lean,-31,13,7,'#353546');rect(27+lean,-30,6,3,'#88f2ec')}
}
ctx.restore();
// small status health bar for boss
if(isEnemy&&p.type==='boss'){rect(x-25,y-77,50,5,'#160d18');rect(x-24,y-76,48*Math.max(0,p.hp/p.max),3,'#ff496a')}
}
function drawHud(){let f=fighters[selected];ctx.fillStyle='#090911b8';ctx.fillRect(14,14,274,68);ctx.fillStyle='#fff';ctx.font='800 16px sans-serif';ctx.fillText(f.name.toUpperCase(),26,37);ctx.fillStyle='#b8adbe';ctx.font='11px sans-serif';ctx.fillText(f.style.toUpperCase(),26,55);ctx.fillStyle='#160e18';ctx.fillRect(26,64,200,9);let hg=ctx.createLinearGradient(26,0,226,0);hg.addColorStop(0,'#ff426f');hg.addColorStop(1,'#ff996a');ctx.fillStyle=hg;ctx.fillRect(27,65,198*Math.max(0,player.hp/player.max),7);ctx.fillStyle='#110e17';ctx.fillRect(26,76,200,5);ctx.fillStyle='#edbc4f';ctx.fillRect(27,77,198*player.special/100,3);ctx.fillStyle='#fff';ctx.font='bold 11px sans-serif';ctx.fillText('SCORE  '+score.toLocaleString(),790,30);ctx.fillStyle='#ffcc77';ctx.fillText('STAGE '+String(stage+1).padStart(2,'0')+' / 09',790,49);if(combo>1&&comboTimer>0){ctx.font='900 22px sans-serif';ctx.fillStyle='#ffd16a';ctx.fillText(`${combo} HIT COMBO!`,735,80)}}

